// <auto-generated-scaffold>
//   fill-zero-hours — the automated trigger. Hand-written; regeneration keeps this file.
// </auto-generated-scaffold>
#nullable enable
using Marten;
using Wolverine;
using Wolverine.Http;
using HourBooking.Views;

namespace HourBooking.Slices.Booking;

/// <summary>
/// The ZeroFillProcessor: <c>Event(s) -> View -> AUTOMATED TRIGGER -> Command -> Event(s)</c>.
///
/// It is a TRIGGER, not an event handler — a peer of a person at a screen. It never receives an event
/// and it never emits one. It reads two views and issues a command, which is the whole of what the
/// model draws:
///
///   ZeroFillTodo -> ZeroFillProcessor    the work: one row per (employee, project) still to fill
///   WorkingDays  -> ZeroFillProcessor    which days it is allowed to fill
///   ZeroFillProcessor -> FillZeroHours   the command, one per day
///
/// Both rules the model states about WHICH days get filled are enforced right here, because both are
/// questions about a view rather than about the stream:
///
///   GWT 1  the rest of THAT month, one event per day — the row's effectiveFrom to its month end.
///   GWT 2  only working days — the days WorkingDays holds a row for, and nothing else. There is no
///          DayOfWeek arithmetic anywhere in this slice: a working Saturday is filled and a public
///          holiday is not, entirely because of what the Google calendar published.
///
/// GWT 4 (AlreadyFilled) is enforced twice on purpose. Here it is the todo list's tick-off, which stops
/// the processor working the same row twice and costs nothing; in FillZeroHoursHandler it is the rule in
/// the transaction, which is what actually holds.
///
/// TRANSPORT, which the model deliberately does not state. The tick arrives as an HTTP POST, so a
/// scheduler, an operator or a test can all drive it the same way; a Marten subscription that notified
/// this processor instead would be equally legal, because the shape rule is view -> command and says
/// nothing about what wakes the processor up. What there is NOT is a background timer: a timer firing
/// inside the test host would fill zeros nobody asked for and every other slice's GIVEN would stop
/// meaning what it says.
/// </summary>
public static class ZeroFillProcessor
{
    public const string TickRoute = "/automation/zero-fill/run";

    [WolverinePost(TickRoute)]
    public static async Task<ZeroFillRun> Run(
        IQuerySession session,
        IMessageBus bus,
        CancellationToken cancellation)
    {
        // Pending, not every row: a row that only ever saw a tick-off is not work. See ZeroFillTodo.
        var work = await session.Query<ZeroFillTodo>()
            .Where(r => r.Pending)
            .OrderBy(r => r.Id)
            .ToListAsync(cancellation);

        var filled = new List<ZeroFillRun.Day>();
        var skipped = new List<ZeroFillRun.Day>();

        foreach (var row in work)
        {
            foreach (var day in await WorkingDaysToFill(session, row, cancellation))
            {
                // The tick-off. The decider would refuse this anyway, so this is cheapness, not safety.
                if (row.IsFilled(day)) continue;

                var outcome = await bus.InvokeAsync<ZeroFillOutcome>(new FillZeroHours(
                    // terminal="bookingId:generated" — the trigger mints the id; no upstream carries it.
                    Guid.NewGuid(),
                    row.EmployeeId,
                    row.Month,
                    row.ProjectId,
                    day,
                    // terminal="hours:const" — 0. The decider writes the constant regardless.
                    FillZeroHoursState.ZeroHours), cancellation);

                (outcome.WasFilled ? filled : skipped)
                    .Add(new ZeroFillRun.Day(row.EmployeeId, row.ProjectId, day, outcome.Rule));
            }
        }

        return new ZeroFillRun(filled, skipped);
    }

    /// <summary>
    /// "The rest of that month" intersected with "only working days". Month equality is the query and
    /// the date window is applied in memory: at most 31 rows, and it keeps DateOnly comparisons out of
    /// the generated SQL.
    /// </summary>
    private static async Task<IReadOnlyList<DateOnly>> WorkingDaysToFill(
        IQuerySession session, ZeroFillTodo row, CancellationToken cancellation)
    {
        var published = await session.Query<WorkingDays>()
            .Where(d => d.Month == row.Month)
            .ToListAsync(cancellation);

        return published
            .Select(d => d.Date)
            .Where(d => d >= row.EffectiveFrom)
            .OrderBy(d => d)
            .ToList();
    }
}

/// <summary>
/// What one tick did. Not a domain concept and not persisted — an automation with no visible output is
/// impossible to operate, and it is what lets a test see that a day was SKIPPED for a named rule rather
/// than silently never attempted.
/// </summary>
public sealed record ZeroFillRun(IReadOnlyList<ZeroFillRun.Day> Filled, IReadOnlyList<ZeroFillRun.Day> Skipped)
{
    public sealed record Day(Guid EmployeeId, Guid ProjectId, DateOnly Date, string? Rule);
}
